{
  "影像诊断模板": {
    "输入字段": ["解剖位置", "大小", "形态", "密度", "边界", "增强方式", "其他特征"],
    "特征组合规则": [
      {"如果": {"解剖位置": "右肺上叶"}, "并且": {"大小": ">2cm"}, "则": {"推荐诊断": ["肺腺癌"]}},
      {"如果": {"形态": "分叶状"}, "并且": {"边界": "毛糙"}, "则": {"推荐诊断": ["恶性肿瘤"]}}
    ],
    "诊断推理规则": [
      {"如果": {"大小": ">2cm", "形态": "分叶状", "密度": "高"}, "则": {"可能的诊断": ["肺癌"]}},
      {"如果": {"边界": "光滑", "增强方式": "明显强化"}, "则": {"可能的诊断": ["感染性病变"]}
    ]
  },
  "诊断描述模板": {
    "诊断列表": [
      {
        "诊断": "肺腺癌",
        "描述模板": [
          "{解剖位置}可见一枚约{大小}大小的{形态}软组织密度影，边缘{边界}{其他特征}",
          "增强扫描后呈{增强方式}"
        ]
      },
      {
        "诊断": "肺炎",
        "描述模板": [
          "{解剖位置}可见一斑片状或大片状实变影，其内可见小支气管充气征，边缘模糊。",
          "增强扫描病灶无明显强化"
        ]
      }
    ]
  }
}
